function [p] = ecliptic_to_j2000(l, b, r)
%ECLIPTIC_TO_J2000  Ecliptic longitude, latitude [rad] and distance to the mean equator and equinox of J2000 (a rotation about x by the
%   obliquity).
%   l: real[1] (passed a plain number)
%   b: real[1] (passed a plain number)
%   r: real[m] (passed in m)
%   returns p: real[m][3] (passed in m)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    p = zeros(3, 1);
    x = ((r * cos(b)) * cos(l));
    y = ((r * cos(b)) * sin(l));
    z = (r * sin(b));
    eps = (23.43929111 * 0.017453292519943295);
    p = [x; ((cos(eps) * y) - (sin(eps) * z)); ((sin(eps) * y) + (cos(eps) * z))];
end
